describe("local practice", () => {
  it("intercept a request", () => {
    cy.intercept("GET", "/books.json", { body: [{ title: "Moon" }] }).as("books");
    cy.visit("/practice.html");
    cy.window().then(win => win.fetch("/books.json"));
    cy.wait("@books").its("response.statusCode").should("eq", 200);
  });
});
